interface VehicleWithDescription {
    String getName();          // abstrakcyjna - KAZDA klasa musi zaimplementowac
    int getMaxSpeed();         // abstrakcyjna - KAZDA klasa musi zaimplementowac

    default String describe() {   // default - implementacja opcjonalna do nadpisania
        return getName() + " (max " + getMaxSpeed() + " km/h)";
    }

    static VehicleWithDescription of(String name, int maxSpeed) {  // static - fabryka
        return new VehicleWithDescription() {
            public String getName() { return name; }
            public int getMaxSpeed() { return maxSpeed; }
        };
    }
}

class Car implements VehicleWithDescription {
    public String getName() { return "Samochod"; }
    public int getMaxSpeed() { return 180; }
    // brak describe() - Car dostaje ja "za darmo" z interfejsu
}

Car car = new Car();
assertThat(car.describe()).isEqualTo("Samochod (max 180 km/h)");

class SportsCar implements VehicleWithDescription {
    public String getName() { return "Bolid"; }
    public int getMaxSpeed() { return 320; }

    @Override
    public String describe() {
        return "\uD83C\uDFCE " + VehicleWithDescription.super.describe();
    }
}

assertThat(new SportsCar().describe()).isEqualTo("\uD83C\uDFCE Bolid (max 320 km/h)");

interface Floatable { default String move() { return "plynie"; } }
interface Drivable  { default String move() { return "jedzie"; } }

class Amphibious implements Floatable, Drivable {
    // BLAD KOMPILACJI: class Amphibious inherits unrelated defaults for move() from types Floatable and Drivable
